calc <- function(expr) {
  expr <- gsub(" ", "", expr)
  nums <- as.numeric(strsplit(expr, "[-+*/]")[[1]])
  ops <- strsplit(gsub("[0-9.]", "", expr), "")[[1]]
  vals <- nums[1]
  pending <- character(0)
  for (i in seq_along(ops)) {
    if (ops[i] == "*") {
      vals[length(vals)] <- vals[length(vals)] * nums[i + 1]
    } else if (ops[i] == "/") {
      vals[length(vals)] <- vals[length(vals)] / nums[i + 1]
    } else {
      pending <- c(pending, ops[i])
      vals <- c(vals, nums[i + 1])
    }
  }
  result <- vals[1]
  for (j in seq_along(pending)) {
    result <- if (pending[j] == "+") result + vals[j + 1] else result - vals[j + 1]
  }
  result
}
